corrected_code:
import { db } from '../db';

export async function routeDiagnosticReportActivity(input: {
  reportId: string;
  targetPractitionerId: string;
  clinicalFolderId: string;
  authorizingDoctorId: string;
}) {
  const { reportId, targetPractitionerId, clinicalFolderId, authorizingDoctorId } = input;

  const authCheck = await db.query(
    'SELECT r.id FROM lab_reports r JOIN patient_care_teams pct ON r.patient_id = pct.patient_id WHERE r.id = $1 AND pct.doctor_id = $2',
    [reportId, authorizingDoctorId]
  );
  if (authCheck.rowCount === 0) {
    throw new Error('Access denied: authorizing doctor is not on the patient care team');
  }

  const updated = await db.query(
    'UPDATE lab_reports SET assigned_doctor_id = $1, folder_id = $2, routed_at = NOW() WHERE id = $3 RETURNING *',
    [targetPractitionerId, clinicalFolderId, reportId]
  );

  return updated.rows[0];
}
